using System.Globalization;
using TomasAI.IFM.UI.Net.ViewModels.Trade;
public sealed class BrokerTradePreviewPresentationTests
{
 static readonly BrokerTradeLegData[] Legs=[new("SC","-SC",110,2,2.4m,.16,true,0.2,50),new("LC","+LC",120,.5m,.7m,.10,true,0.1,50),new("SP","-SP",90,2,2.4m,-.16,false,0.2,50),new("LP","+LP",80,.5m,.7m,-.10,false,0.1,50)];
 [Theory][InlineData(1,160,340)][InlineData(2,320,680)][InlineData(10,1600,3400)]public void Balanced_condor_uses_the_WinForms_net_price_and_payoff_formula(int quantity,decimal profit,decimal loss){var result=BrokerTradePreviewPresentation.Calculate(Legs,Legs.ToDictionary(x=>x.ContractId,_=>quantity),quantity,null,null);Assert.Equal(-3.2m,result.OrderPrice);Assert.Equal(profit,decimal.Parse(result.Fields["Max profit"],CultureInfo.CurrentCulture));Assert.Equal(loss,decimal.Parse(result.Fields["Max loss"],CultureInfo.CurrentCulture));Assert.Equal(profit,decimal.Parse(result.Fields["Est. credit"],CultureInfo.CurrentCulture));Assert.Equal("0",result.Fields["Net delta"]);}
 [Fact]public void Operator_price_is_used_in_economics(){var result=BrokerTradePreviewPresentation.Calculate(Legs,Legs.ToDictionary(x=>x.ContractId,_=>2),2,-3.15m,null);Assert.Equal(-3.15m,result.OrderPrice);Assert.Equal(315m,decimal.Parse(result.Fields["Max profit"],CultureInfo.CurrentCulture));}
 [Fact]public void Missing_quotes_do_not_generate_an_order_price(){var legs=new[]{Legs[0] with{Bid=null}};var result=BrokerTradePreviewPresentation.Calculate(legs,new Dictionary<string,int>{{"SC",1}},1,null,null);Assert.Null(result.OrderPrice);Assert.Equal("Select priced strategy legs",result.Fields["Validation"]);}
 [Fact]public void Futures_accept_an_operator_price_without_fabricated_quotes(){var leg=new BrokerTradeLegData("ES","+Future",null,null,null,1,false,0,50,IsFuture:true);var result=BrokerTradePreviewPresentation.Calculate([leg],new Dictionary<string,int>{{"ES",2}},2,7800m,null);Assert.Equal(7800m,result.OrderPrice);Assert.Equal("Reference price only - market quote required",result.Fields["Validation"]);}
 [Fact]public void Stored_legs_preserve_contract_direction_multiplier_and_do_not_invent_quotes(){var rows=BrokerTradePreviewPresentation.StoredLegs(new TomasAI.IFM.Domain.Trade.Shared.TradeOrderComponentDefinition{Legs=[new(){ContractId="C",AssetFamily=TomasAI.IFM.Domain.Trade.Shared.TradeAssetFamily.FuturesOption,SignedQuantity=-2,PutCall=1,Strike=110,CashMultiplier=50},new(){ContractId="P",AssetFamily=TomasAI.IFM.Domain.Trade.Shared.TradeAssetFamily.FuturesOption,SignedQuantity=2,PutCall=2,Strike=90,CashMultiplier=50}]});Assert.Equal("-SC",rows[0].Role);Assert.Equal("+LP",rows[1].Role);Assert.Equal(50m,rows[0].Multiplier);Assert.All(rows,x=>{Assert.Null(x.Bid);Assert.Null(x.Ask);Assert.Null(x.Delta);});}
}
